    function loadState() {
        var raw = null;
        try { raw = localStorage.getItem(STORAGE_KEY); } catch (e) { return false; }
        if (!raw) return false;
        try {
            var parsed = JSON.parse(raw);
            if (!parsed || !parsed.state) return false;
            Object.keys(state).forEach(function (key) {
                if (parsed.state[key] !== undefined) state[key] = parsed.state[key];
            });
            messageWasEditedByUser = !!parsed.messageWasEditedByUser;

            // Resume the id counter above the highest restored id so newly
            // added rules/numbers can't collide with restored ones.
            var maxId = 0;
            function trackMaxId(obj) {
                var n = parseInt(String(obj.id || "").replace("id", ""), 10);
                if (!isNaN(n) && n > maxId) maxId = n;
            }
            (state.rules || []).concat(state.pathRules || []).forEach(function (r) {
                trackMaxId(r);
                (r.numbers || []).forEach(trackMaxId);
            });
            uidCounter = maxId;
            return true;
        } catch (e) {
            return false;
        }
    }

